#include <Arduino.h>
const int LED_PINS[] = {2, 3, 4};  
const int pins[] = {5, 6, 7, 8, 9, 10, 11, 12, 13, 44, 45};

void setup();
void loop();
void setup() {
  for (int i = 0; i < 3; i++) {
    pinMode(LED_PINS[i], OUTPUT);
    digitalWrite(LED_PINS[i], LOW);
  }
  for (int i = 0; i < 10; i++) {
      digitalWrite(pins[i], LOW);
  }
}
void loop() {
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED_PINS[i], HIGH);  
    digitalWrite(5, HIGH);  
    delay(2000);  
    digitalWrite(LED_PINS[i], LOW);  
    digitalWrite(5, LOW);  
  }
  for (int i = 0; i < 10; i++) {
      digitalWrite(pins[i], HIGH);
  }
  delay(2000);
  for (int i = 0; i < 10; i++) {
      digitalWrite(pins[i], LOW);
  }
}
